-- 4. Questions (Topic 41: AWS Core Services - 13 Questions)
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
-- Simple
('60000000-0000-0000-0000-000000000701', '50000000-0000-0000-0000-000000000041', 'simple', 'mcq', 'What does EC2 stand for in AWS?', '["Elastic Cloud Compute", "Easy Computer Connect", "Edge Cloud Core", "Elastic Cloud Connection"]', 'Elastic Cloud Compute', 'EC2 provides scalable computing capacity in the AWS cloud.', 'active'),
('60000000-0000-0000-0000-000000000702', '50000000-0000-0000-0000-000000000041', 'simple', 'mcq', 'Which AWS service is used for object storage?', '["EBS", "S3", "RDS", "DynamoDB"]', 'S3', 'Amazon Simple Storage Service (S3) is used for scalable object storage.', 'active'),
('60000000-0000-0000-0000-000000000703', '50000000-0000-0000-0000-000000000041', 'simple', 'mcq', 'What is the purpose of Amazon RDS?', '["To store media files", "To manage relational databases in the cloud", "To serve DNS requests", "To route network traffic"]', 'To manage relational databases in the cloud', 'RDS makes it easy to set up, operate, and scale relational databases.', 'active'),
('60000000-0000-0000-0000-000000000704', '50000000-0000-0000-0000-000000000041', 'simple', 'mcq', 'Which service provides a content delivery network (CDN) in AWS?', '["CloudFront", "Route 53", "VPC", "Direct Connect"]', 'CloudFront', 'CloudFront safely delivers data, videos, applications, and APIs to customers globally with low latency.', 'active'),
-- Intermediate
('60000000-0000-0000-0000-000000000705', '50000000-0000-0000-0000-000000000041', 'intermediate', 'mcq', 'What is an "Availability Zone" (AZ)?', '["A specific data center location", "A collection of one or more discrete data centers with redundant power and networking", "A whole AWS region", "A type of EC2 instance"]', 'A collection of one or more discrete data centers with redundant power and networking', 'AZs provide high availability and fault tolerance within a Region.', 'active'),
('60000000-0000-0000-0000-000000000706', '50000000-0000-0000-0000-000000000041', 'intermediate', 'mcq', 'What is the difference between EBS and S3?', '["EBS is object storage, S3 is block storage", "EBS is network-attached block storage for EC2, while S3 is scalable object storage", "EBS is slower than S3", "S3 is only for internal AWS use"]', 'EBS is network-attached block storage for EC2, while S3 is scalable object storage', 'EBS is used for file systems and databases on EC2 instances.', 'active'),
('60000000-0000-0000-0000-000000000707', '50000000-0000-0000-0000-000000000041', 'intermediate', 'mcq', 'What does "Auto Scaling" do for EC2 instances?', '["Automatically reboots instances", "Automatically adds or removes instances based on demand", "Increases the price of instances", "Updates the OS"]', 'Automatically adds or removes instances based on demand', 'Auto Scaling ensures you have the right number of instances to handle the load.', 'active'),
('60000000-0000-0000-0000-000000000708', '50000000-0000-0000-0000-000000000041', 'intermediate', 'mcq', 'What is a VPC (Virtual Private Cloud)?', '["A type of physical server", "A logically isolated section of the AWS cloud", "A database system", "A cloud-based desktop"]', 'A logically isolated section of the AWS cloud', 'VPC gives you full control over your virtual networking environment.', 'active'),
-- Expert
('60000000-0000-0000-0000-000000000709', '50000000-0000-0000-0000-000000000041', 'expert', 'mcq', 'What is the "Shared Responsibility Model" in AWS?', '["AWS shared the profit with customers", "AWS manages security OF the cloud, while customers manage security IN the cloud", "Customer manages all security", "AWS manages all security"]', 'AWS manages security OF the cloud, while customers manage security IN the cloud', 'Customers are responsible for securing their data, OS, and applications.', 'active'),
('60000000-0000-0000-0000-000000000710', '50000000-0000-0000-0000-000000000041', 'expert', 'mcq', 'Explain the purpose of "Multi-AZ" deployment for RDS.', '["To increase storage speed", "To provide high availability and automatic failover", "To reduce network latency", "To save money"]', 'To provide high availability and automatic failover', 'In a Multi-AZ deployment, AWS automatically provisions and maintains a synchronous standby replica.', 'active'),
('60000000-0000-0000-0000-000000000711', '50000000-0000-0000-0000-000000000041', 'expert', 'mcq', 'What is the "Placement Group" in EC2?', '["A way to group instances by region", "A strategy for placing instances based on network and hardware requirements", "A type of billing plan", "A security group"]', 'A strategy for placing instances based on network and hardware requirements', 'Placement groups can be Cluster (low latency), Spread (redundancy), or Partition (large distributed workloads).', 'active'),
('60000000-0000-0000-0000-000000000712', '50000000-0000-0000-0000-000000000041', 'expert', 'mcq', 'What is AWS Direct Connect?', '["A type of ethernet cable", "A cloud service that makes it easy to establish a dedicated network connection from on-premises to AWS", "A faster version of S3", "A cloud-based router"]', 'A cloud service that makes it easy to establish a dedicated network connection from on-premises to AWS', 'Direct Connect provides consistent network performance and reduces bandwidth costs.', 'active'),
('60000000-0000-0000-0000-000000000713', '50000000-0000-0000-0000-000000000041', 'expert', 'mcq', 'Which service is used for managing micro-segmentation in a VPC?', '["Security Groups", "IAM Roles", "Route Tables", "Egress-only Gateways"]', 'Security Groups', 'Security groups act as a virtual firewall for your EC2 instances to control incoming and outgoing traffic.', 'active');

-- Topic 42: Azure Fundamentals (13 Questions)
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
-- Simple
('60000000-0000-0000-0000-000000000714', '50000000-0000-0000-0000-000000000042', 'simple', 'mcq', 'What is Microsoft Azure?', '["A web browser", "A cloud computing platform", "An operating system", "A programming language"]', 'A cloud computing platform', 'Azure is Microsoft''s public cloud computing platform.', 'active'),
('60000000-0000-0000-0000-000000000715', '50000000-0000-0000-0000-000000000042', 'simple', 'mcq', 'What is an "Azure Resource Group"?', '["A type of server", "A logical container for resources deployed on Azure", "A billing unit", "A network policy"]', 'A logical container for resources deployed on Azure', 'Resource groups help manage and organize related Azure resources.', 'active'),
('60000000-0000-0000-0000-000000000716', '50000000-0000-0000-0000-000000000042', 'simple', 'mcq', 'Which Azure service is used for data storage in the form of blobs, files, and queues?', '["Azure SQL Database", "Azure Storage Accounts", "Cosmos DB", "Virtual Machines"]', 'Azure Storage Accounts', 'Storage accounts provide a unique namespace for your Azure Storage data.', 'active'),
('60000000-0000-0000-0000-000000000717', '50000000-0000-0000-0000-000000000042', 'simple', 'mcq', 'What is "Azure Active Directory" (now Microsoft Entra ID)?', '["A database", "A cloud-based identity and access management service", "A virtual private network", "A file explorer"]', 'A cloud-based identity and access management service', 'Azure AD helps employees sign in and access resources.', 'active'),
-- Intermediate
('60000000-0000-0000-0000-000000000718', '50000000-0000-0000-0000-000000000042', 'intermediate', 'mcq', 'What is the "Azure Advisor"?', '["A customer support bot", "A personalized cloud consultant that helps you follow best practices", "A billing tool", "A performance monitor"]', 'A personalized cloud consultant that helps you follow best practices', 'Advisor analyzes your resource configuration to help optimize deployments.', 'active'),
('60000000-0000-0000-0000-000000000719', '50000000-0000-0000-0000-000000000042', 'intermediate', 'mcq', 'What is "Azure Resource Manager" (ARM)?', '["A type of hardware", "The deployment and management service for Azure", "A database engine", "A network router"]', 'The deployment and management service for Azure', 'ARM is responsible for creating, updating, and deleting resources in your Azure account.', 'active'),
('60000000-0000-0000-0000-000000000720', '50000000-0000-0000-0000-000000000042', 'intermediate', 'mcq', 'What is the purpose of "Availability Sets" in Azure?', '["To increase CPU speed", "To ensure high availability by placing VMs across different hardware in a datacenter", "To group resources by region", "To backup data"]', 'To ensure high availability by placing VMs across different hardware in a datacenter', 'Availability sets protect against hardware failures or maintenance events.', 'active'),
('60000000-0000-0000-0000-000000000721', '50000000-0000-0000-0000-000000000042', 'intermediate', 'mcq', 'What is "Azure Monitor"?', '["A physical screen", "A service for collecting, analyzing, and acting on telemetry from cloud and on-premises environments", "A security guard", "A billing dashboard"]', 'A service for collecting, analyzing, and acting on telemetry from cloud and on-premises environments', 'Azure Monitor helps maximize the availability and performance of your applications.', 'active'),
-- Expert
('60000000-0000-0000-0000-000000000722', '50000000-0000-0000-0000-000000000042', 'expert', 'mcq', 'What is "Azure Blueprints"?', '["A design document", "A way to orchestrate the deployment of various resource templates and other artifacts", "A type of virtual network", "A cloud security standard"]', 'A way to orchestrate the deployment of various resource templates and other artifacts', 'Blueprints enable cloud architects to define a repeatable set of Azure resources.', 'active'),
('60000000-0000-0000-0000-000000000723', '50000000-0000-0000-0000-000000000042', 'expert', 'mcq', 'Explain "Azure Traffic Manager".', '["A road safety system", "A DNS-based traffic load balancer", "A virtual router", "A bandwidth monitor"]', 'A DNS-based traffic load balancer', 'Traffic Manager allows you to distribute traffic optimally to services across global Azure regions.', 'active'),
('60000000-0000-0000-0000-000000000724', '50000000-0000-0000-0000-000000000042', 'expert', 'mcq', 'What is "Azure Policy"?', '["A set of terms and conditions", "A service to create, assign and, manage policies that enforce different rules over your resources", "A document for insurance", "A network rule"]', 'A service to create, assign and, manage policies that enforce different rules over your resources', 'Azure Policy helps ensure that your resources stay compliant with your corporate standards.', 'active'),
('60000000-0000-0000-0000-000000000725', '50000000-0000-0000-0000-000000000042', 'expert', 'mcq', 'What is the purpose of "Azure ExpressRoute"?', '["A fast internet connection", "A private connection between on-premises infrastructure and Azure datacenters", "A cloud-based courier service", "A way to speed up SQL queries"]', 'A private connection between on-premises infrastructure and Azure datacenters', 'ExpressRoute connections do not go over the public Internet.', 'active'),
('60000000-0000-0000-0000-000000000726', '50000000-0000-0000-0000-000000000042', 'expert', 'mcq', 'What is "Azure Governance"?', '["Management of the government", "Mechanisms and processes that maintain control over resources in Azure", "A set of laws", "Cloud-based voting"]', 'Mechanisms and processes that maintain control over resources in Azure', 'Governance includes aspects like resource management, cost management, and security.', 'active'),

-- Topic 43: AWS Lambda & Serverless Design (13 Questions)
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
-- Simple
('60000000-0000-0000-0000-000000000727', '50000000-0000-0000-0000-000000000043', 'simple', 'mcq', 'What is AWS Lambda?', '["A virtual machine service", "A serverless compute service that runs code in response to events", "A database engine", "A file storage system"]', 'A serverless compute service that runs code in response to events', 'Lambda allows you to run code without provisioning or managing servers.', 'active'),
('60000000-0000-0000-0000-000000000728', '50000000-0000-0000-0000-000000000043', 'simple', 'mcq', 'In serverless, "Cold Start" refers to:', '["The time a computer takes to boot in winter", "The latency when a function is triggered after being idle", "Starting the cloud provider console", "Rebooting a database"]', 'The latency when a function is triggered after being idle', 'AWS needs to spin up a new execution environment for the first request after a long idle time.', 'active'),
('60000000-0000-0000-0000-000000000729', '50000000-0000-0000-0000-000000000043', 'simple', 'mcq', 'Which service orchestrates multiple lambda functions into workflows?', '["AWS Step Functions", "AWS Glue", "AWS Batch", "AWS CloudFormation"]', 'AWS Step Functions', 'Step Functions allow you to build complex distributed applications as state machines.', 'active'),
('60000000-0000-0000-0000-000000000730', '50000000-0000-0000-0000-000000000043', 'simple', 'mcq', 'What is the maximum execution time (timeout) for an AWS Lambda function?', '["1 minute", "5 minutes", "15 minutes", "1 hour"]', '15 minutes', 'AWS Lambda functions have a maximum timeout limit of 900 seconds (15 minutes).', 'active'),
-- Intermediate
('60000000-0000-0000-0000-000000000731', '50000000-0000-0000-0000-000000000043', 'intermediate', 'mcq', 'What is the "Function-as-a-Service" (FaaS) model?', '["Software delivered as a service", "Infrastructure delivered as a service", "Executing code blocks without managing the underlying platform or infrastructure", "Providing a whole OS"]', 'Executing code blocks without managing the underlying platform or infrastructure', 'FaaS is the core concept of serverless computing.', 'active'),
('60000000-0000-0000-0000-000000000732', '50000000-0000-0000-0000-000000000043', 'intermediate', 'mcq', 'What triggers an AWS Lambda function?', '["A cron schedule only", "Events from AWS services like S3 or DynamoDB", "Manual invocation only", "A specific hardware button"]', 'Events from AWS services like S3 or DynamoDB', 'Lambda is designed to be event-driven.', 'active'),
('60000000-0000-0000-0000-000000000733', '50000000-0000-0000-0000-000000000043', 'intermediate', 'mcq', 'What is an "EventBridge" in AWS?', '["A networking cable", "A serverless event bus that makes it easy to connect applications using data from your own apps", "A UI component", "A database connector"]', 'A serverless event bus that makes it easy to connect applications using data from your own apps', 'EventBridge simplifies the process of building event-driven architectures.', 'active'),
('60000000-0000-0000-0000-000000000734', '50000000-0000-0000-0000-000000000043', 'intermediate', 'mcq', 'How are AWS Lambda functions priced?', '["Flat monthly fee", "Based on the number of requests and the duration (GB-seconds)", "By the amount of code written", "By the number of developers"]', 'Based on the number of requests and the duration (GB-seconds)', 'You pay only for the compute time you consume.', 'active'),
-- Expert
('60000000-0000-0000-0000-000000000735', '50000000-0000-0000-0000-000000000043', 'expert', 'mcq', 'What is "Provisioned Concurrency" in AWS Lambda?', '["Pre-assigning CPU to instances", "Keeping a specified number of execution environments initialized and ready to respond immediately", "A way to save costs", "A limit on how many developers can use the function"]', 'Keeping a specified number of execution environments initialized and ready to respond immediately', 'Provisioned Concurrency eliminates cold start latency for highly consistent response times.', 'active'),
('60000000-0000-0000-0000-000000000736', '50000000-0000-0000-0000-000000000043', 'expert', 'mcq', 'Explain the purpose of "Dead Letter Queues" (DLQ) in Lambda.', '["To store deleted emails", "To capture and store events that failed to process correctly", "To manage history", "To increase speed"]', 'To capture and store events that failed to process correctly', 'DLQs allow you to debug failed asynchronous invocations.', 'active'),
('60000000-0000-0000-0000-000000000737', '50000000-0000-0000-0000-000000000043', 'expert', 'mcq', 'What is the role of "Layers" in AWS Lambda?', '["To define the physical hardware", "A mechanism to package libraries and other dependencies that can be shared across multiple functions", "To manage networking layers", "To set up billing hierarchies"]', 'A mechanism to package libraries and other dependencies that can be shared across multiple functions', 'Layers reduce the size of your deployment package and keep your function code focused.', 'active'),
('60000000-0000-0000-0000-000000000738', '50000000-0000-0000-0000-000000000043', 'expert', 'mcq', 'What is "Fan-out" pattern in serverless?', '["Cooling down the servers", "Using a single event to trigger multiple downstream actions or services in parallel", "Spreading files across regions", "Closing all connections"]', 'Using a single event to trigger multiple downstream actions or services in parallel', 'Fan-out is often implemented using SNS or EventBridge.', 'active'),
('60000000-0000-0000-0000-000000000739', '50000000-0000-0000-0000-000000000043', 'expert', 'mcq', 'In a serverless environment, what is "Idempotency"?', '["The ability to delete all data", "Ensuring that performing an operation multiple times has the same effect as performing it once", "Making code runs faster", "Thread safety"]', 'Ensuring that performing an operation multiple times has the same effect as performing it once', 'Idempotency is crucial for handling retries in event-driven systems.', 'active'),

-- Topic 44: Containers & Kubernetes (EKS/AKS) (13 Questions)
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
-- Simple
('60000000-0000-0000-0000-000000000740', '50000000-0000-0000-0000-000000000044', 'simple', 'mcq', 'What is a "Container" in cloud computing?', '["A physical box for servers", "A lightweight, standalone, executable package of software that includes everything needed to run it", "A type of database", "A network router"]', 'A lightweight, standalone, executable package of software that includes everything needed to run it', 'Containers provide isolation and consistency across different environments.', 'active'),
('60000000-0000-0000-0000-000000000741', '50000000-0000-0000-0000-000000000044', 'simple', 'mcq', 'What is Kubernetes (k8s)?', '["A programming language", "An open-source system for automating deployment, scaling, and management of containerized applications", "A container runtime", "A cloud provider"]', 'An open-source system for automating deployment, scaling, and management of containerized applications', 'Kubernetes is the leading container orchestration platform.', 'active'),
('60000000-0000-0000-0000-000000000742', '50000000-0000-0000-0000-000000000044', 'simple', 'mcq', 'What is the smallest deployable unit in Kubernetes?', '["Container", "Pod", "Node", "Namespace"]', 'Pod', 'A Pod represents a single instance of a running process in your cluster.', 'active'),
('60000000-0000-0000-0000-000000000743', '50000000-0000-0000-0000-000000000044', 'simple', 'mcq', 'Which AWS service is used for managing Kubernetes clusters?', '["ECS", "EKS", "ECR", "Fargate"]', 'EKS', 'Amazon Elastic Kubernetes Service (EKS) is a managed Kubernetes service.', 'active'),
-- Intermediate
('60000000-0000-0000-0000-000000000744', '50000000-0000-0000-0000-000000000044', 'intermediate', 'mcq', 'What is a "Node" in a Kubernetes cluster?', '["A UI component", "A worker machine (either VM or physical)", "A type of pod", "A network policy"]', 'A worker machine (either VM or physical)', 'Nodes are where the applications (Pods) actually run.', 'active'),
('60000000-0000-0000-0000-000000000745', '50000000-0000-0000-0000-000000000044', 'intermediate', 'mcq', 'What does the "Kubelet" do?', '["It is a database engine", "An agent that runs on each node in the cluster and ensures containers are running in a pod", "The API server", "A monitoring tool"]', 'An agent that runs on each node in the cluster and ensures containers are running in a pod', 'Kubelet is responsible for maintaining the health of Pods on a Node.', 'active'),
('60000000-0000-0000-0000-000000000746', '50000000-0000-0000-0000-000000000044', 'intermediate', 'mcq', 'What is an "Ingress" in Kubernetes?', '["A way to delete pods", "An API object that manages external access to the services in a cluster", "A type of security group", "A logging system"]', 'An API object that manages external access to the services in a cluster', 'Ingress typically provides load balancing, SSL termination, and name-based virtual hosting.', 'active'),
('60000000-0000-0000-0000-000000000747', '50000000-0000-0000-0000-000000000044', 'intermediate', 'mcq', 'What is "AWS Fargate"?', '["A new type of database", "A serverless compute engine for containers that works with both ECS and EKS", "A network monitor", "A billing plan"]', 'A serverless compute engine for containers that works with both ECS and EKS', 'Fargate allows you to run containers without managing the underlying EC2 instances.', 'active'),
-- Expert
('60000000-0000-0000-0000-000000000748', '50000000-0000-0000-0000-000000000044', 'expert', 'mcq', 'What is "etcd" in Kubernetes?', '["A UI dashboard", "A consistent and highly-available key value store used as Kubernetes'' backing store for all cluster data", "A container runtime", "A logging agent"]', 'A consistent and highly-available key value store used as Kubernetes'' backing store for all cluster data', 'etcd stores the state of the entire Kubernetes cluster.', 'active'),
('60000000-0000-0000-0000-000000000749', '50000000-0000-0000-0000-000000000044', 'expert', 'mcq', 'Explain "Horizontal Pod Autoscaler" (HPA).', '["Rotating the pods", "Automatically scaling the number of pods in a deployment based on observed CPU utilization", "Scaling the hardware nodes", "A billing alert"]', 'Automatically scaling the number of pods in a deployment based on observed CPU utilization', 'HPA ensures your application can handle varied levels of traffic.', 'active'),
('60000000-0000-0000-0000-000000000750', '50000000-0000-0000-0000-000000000044', 'expert', 'mcq', 'What is a "Sidecar Container" pattern?', '["A backup server", "Placing an extra container in a Pod to enhance or extend the main container''s functionality", "A separate cluster", "A UI component"]', 'Placing an extra container in a Pod to enhance or extend the main container''s functionality', 'Common sidecar uses include logging agents, proxy services, or config watchers.', 'active'),
('60000000-0000-0000-0000-000000000751', '50000000-0000-0000-0000-000000000044', 'expert', 'mcq', 'What is "Helm" in the Kubernetes ecosystem?', '["A steering wheel", "A package manager for Kubernetes that helps you define, install, and upgrade even the most complex Kubernetes applications", "A security standard", "A cloud provider"]', 'A package manager for Kubernetes that helps you define, install, and upgrade even the most complex Kubernetes applications', 'Helm uses "Charts" to package Kubernetes resources.', 'active'),
('60000000-0000-0000-0000-000000000752', '50000000-0000-0000-0000-000000000044', 'expert', 'mcq', 'Explain "Service Mesh" (e.g., Istio, Linkerd).', '["A physical network", "A dedicated infrastructure layer for handling service-to-service communication", "A type of database", "A cloud region"]', 'A dedicated infrastructure layer for handling service-to-service communication', 'Service discovery, load balancing, failure recovery, metrics, and monitoring are common service mesh features.', 'active');

-- Topic 45: Identity & Access Management (IAM) (13 Questions)
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
-- Simple
('60000000-0000-0000-0000-000000000753', '50000000-0000-0000-0000-000000000045', 'simple', 'mcq', 'What is IAM?', '["Internet Access Manager", "Identity and Access Management", "Internal App Monitor", "Instance Access Method"]', 'Identity and Access Management', 'IAM enables you to manage access to AWS services and resources securely.', 'active'),
('60000000-0000-0000-0000-000000000754', '50000000-0000-0000-0000-000000000045', 'simple', 'mcq', 'What is an "IAM User"?', '["A physical person", "An entity that you create in AWS to represent the person or application that uses it to interact with AWS", "A type of database", "A root account"]', 'An entity that you create in AWS to represent the person or application that uses it to interact with AWS', 'IAM users have permanent credentials.', 'active'),
('60000000-0000-0000-0000-000000000755', '50000000-0000-0000-0000-000000000045', 'simple', 'mcq', 'What is "MFA" in IAM?', '["Multi-Factor Authentication", "Main File Access", "Multiple Functional Apps", "Memory File Allocation"]', 'Multi-Factor Authentication', 'MFA adds an extra layer of protection on top of your user name and password.', 'active'),
('60000000-0000-0000-0000-000000000756', '50000000-0000-0000-0000-000000000045', 'simple', 'mcq', 'What is an "IAM Policy"?', '["A set of laws", "A JSON document that defines permissions", "A billing plan", "A network rule"]', 'A JSON document that defines permissions', 'Policies define what actions are allowed or denied on which resources.', 'active'),
-- Intermediate
('60000000-0000-0000-0000-000000000757', '50000000-0000-0000-0000-000000000045', 'intermediate', 'mcq', 'What is an "IAM Role"?', '["A type of user", "An IAM identity that you can create in your account that has specific permissions but no permanent credentials", "A group of users", "A root login"]', 'An IAM identity that you can create in your account that has specific permissions but no permanent credentials', 'IAM roles are intended to be assumed by anyone who needs them, including AWS services.', 'active'),
('60000000-0000-0000-0000-000000000758', '50000000-0000-0000-0000-000000000045', 'intermediate', 'mcq', 'What is the "Principle of Least Privilege"?', '["Giving users full access", "Granting only the minimum permissions required to perform a task", "Hiding all resources", "Sharing admin passwords"]', 'Granting only the minimum permissions required to perform a task', 'Least privilege is a fundamental security best practice.', 'active'),
('60000000-0000-0000-0000-000000000759', '50000000-0000-0000-0000-000000000045', 'intermediate', 'mcq', 'What is "Identity Federation"?', '["A group of cloud providers", "Linking a person''s electronic identity and attributes, stored across multiple distinct identity management systems", "Using one password for everything", "A type of network"]', 'Linking a person''s electronic identity and attributes, stored across multiple distinct identity management systems', 'Federation allows users to sign in using external identities (e.g., from corporate AD).', 'active'),
('60000000-0000-0000-0000-000000000760', '50000000-0000-0000-0000-000000000045', 'intermediate', 'mcq', 'What is "AWS Organizations"?', '["A social club", "An account management service that enables you to consolidate multiple AWS accounts into an organization", "A type of database", "A marketing tool"]', 'An account management service that enables you to consolidate multiple AWS accounts into an organization', 'AWS Organizations helps with centralized billing and policy management.', 'active'),
-- Expert
('60000000-0000-0000-0000-000000000761', '50000000-0000-0000-0000-000000000045', 'expert', 'mcq', 'What are "Service Control Policies" (SCPs)?', '["Rules for customer service", "A type of organization policy used to manage permissions in your organization", "A network firewall rule", "An IAM role"]', 'A type of organization policy used to manage permissions in your organization', 'SCPs offer central control over the maximum available permissions for all accounts in your organization.', 'active'),
('60000000-0000-0000-0000-000000000762', '50000000-0000-0000-0000-000000000045', 'expert', 'mcq', 'Explain "ABAC" (Attribute-Based Access Control) in AWS.', '["A type of encryption", "An authorization strategy that defines permissions based on attributes (tags on users and resources)", "A database query", "A network protocol"]', 'An authorization strategy that defines permissions based on attributes (tags on users and resources)', 'ABAC allows for dynamic and fine-grained permission management.', 'active'),
('60000000-0000-0000-0000-000000000763', '50000000-0000-0000-0000-000000000045', 'expert', 'mcq', 'What is "IAM Access Analyzer"?', '["A password cracker", "A service that helps you identify the resources in your account that are shared with an external entity", "A console logger", "A network sniffer"]', 'A service that helps you identify the resources in your account that are shared with an external entity', 'Access Analyzer uses formal verification to analyze resource policies.', 'active'),
('60000000-0000-0000-0000-000000000764', '50000000-0000-0000-0000-000000000045', 'expert', 'mcq', 'What is the purpose of "Permission Boundaries"?', '["To block all access", "An advanced feature for using a managed policy to set the maximum permissions that an identity-based policy can grant to an IAM entity", "A network router", "A billing limit"]', 'An advanced feature for using a managed policy to set the maximum permissions that an identity-based policy can grant to an IAM entity', 'Permission boundaries prevent privilege escalation.', 'active'),
('60000000-0000-0000-0000-000000000765', '50000000-0000-0000-0000-000000000045', 'expert', 'mcq', 'How does "Cross-Account Access" work in AWS?', '["By copying data", "By allowing an IAM user in one account to assume a role in another account", "By sharing passwords", "By creating a VPN"]', 'By allowing an IAM user in one account to assume a role in another account', 'Cross-account access allows secure resource sharing across different AWS accounts.', 'active');

-- Topic 46: Cloud Network Security (13 Questions)
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
-- Simple
('60000000-0000-0000-0000-000000000766', '50000000-0000-0000-0000-000000000046', 'simple', 'mcq', 'What is a "Security Group" in AWS?', '["A group of security guards", "A virtual firewall for your EC2 instances", "A type of network switch", "An IAM group"]', 'A virtual firewall for your EC2 instances', 'Security groups control inbound and outbound traffic at the instance level.', 'active'),
('60000000-0000-0000-0000-000000000767', '50000000-0000-0000-0000-000000000046', 'simple', 'mcq', 'What is a "WAF"?', '["Web App Firewall", "Wide Area Filter", "Web Access Folder", "Wireless App Framework"]', 'Web App Firewall', 'WAF helps protect your web applications from common web exploits.', 'active'),
('60000000-0000-0000-0000-000000000768', '50000000-0000-0000-0000-000000000046', 'simple', 'mcq', 'What is "DDoS"?', '["Digital Data on Servers", "Distributed Denial of Service", "Dynamic Data optimization System", "Direct Data on Subscription"]', 'Distributed Denial of Service', 'A DDoS attack attempts to make an online service unavailable by overwhelming it with traffic.', 'active'),
('60000000-0000-0000-0000-000000000769', '50000000-0000-0000-0000-000000000046', 'simple', 'mcq', 'What does "AWS Shield" provide?', '["Physical protection for servers", "Protection against DDoS attacks", "A way to encrypt data", "A network router"]', 'Protection against DDoS attacks', 'AWS Shield is a managed DDoS protection service.', 'active'),
-- Intermediate
('60000000-0000-0000-0000-000000000770', '50000000-0000-0000-0000-000000000046', 'intermediate', 'mcq', 'What is an "NACL" (Network Access Control List)?', '["A type of database", "An optional layer of security for your VPC that acts as a firewall for controlling traffic in and out of one or more subnets", "A user list", "A billing report"]', 'An optional layer of security for your VPC that acts as a firewall for controlling traffic in and out of one or more subnets', 'NACLs provide security at the subnet level.', 'active'),
('60000000-0000-0000-0000-000000000771', '50000000-0000-0000-0000-000000000046', 'intermediate', 'mcq', 'What is the difference between Security Groups and NACLs?', '["Security groups are stateless, NACLs are stateful", "Security groups are stateful (inbound allowed -> outbound allowed), NACLs are stateless (rules for both)", "There is no difference", "NACLs are for users"]', 'Security groups are stateful (inbound allowed -> outbound allowed), NACLs are stateless (rules for both)', 'Stateful firewalls remember the state of connections.', 'active'),
('60000000-0000-0000-0000-000000000772', '50000000-0000-0000-0000-000000000046', 'intermediate', 'mcq', 'What is "SSL/TLS Termination"?', '["Stopping a secure connection", "The process of decrypting encrypted traffic before it is passed to the web server", "Hackers breaking encryption", "A security leak"]', 'The process of decrypting encrypted traffic before it is passed to the web server', 'Load balancers often handle SSL termination to reduce load on backend servers.', 'active'),
('60000000-0000-0000-0000-000000000773', '50000000-0000-0000-0000-000000000046', 'intermediate', 'mcq', 'What is an "Amazon Inspector"?', '["A social worker", "An automated security assessment service that helps improve the security and compliance of applications deployed on AWS", "A console monitor", "A billing auditor"]', 'An automated security assessment service that helps improve the security and compliance of applications deployed on AWS', 'Inspector analyzes your instances for vulnerabilities or deviations from best practices.', 'active'),
-- Expert
('60000000-0000-0000-0000-000000000774', '50000000-0000-0000-0000-000000000046', 'expert', 'mcq', 'What is "Deep Packet Inspection" (DPI)?', '["Looking at a packet''s size", "Analyzing the data part of a packet as it passes an inspection point", "A type of database indexing", "A network protocol"]', 'Analyzing the data part of a packet as it passes an inspection point', 'DPI is used for advanced security and network management.', 'active'),
('60000000-0000-0000-0000-000000000775', '50000000-0000-0000-0000-000000000046', 'expert', 'mcq', 'Explain "VPN Peerings" vs "Transit Gateway".', '["VPN is for users, Transit is for servers", "VPC Peering is point-to-point; Transit Gateway acts as a hub that connects multiple VPCs and on-premises networks", "They are identical", "Transit is slower"]', 'VPC Peering is point-to-point; Transit Gateway acts as a hub that connects multiple VPCs and on-premises networks', 'Transit Gateway simplifies complex network topologies.', 'active'),
('60000000-0000-0000-0000-000000000776', '50000000-0000-0000-0000-000000000046', 'expert', 'mcq', 'What is "BGP" (Border Gateway Protocol) in cloud networking?', '["A billing program", "A protocol used to exchange routing and reachability information between edge routers on the Internet", "A type of UI layout", "A security code"]', 'A protocol used to exchange routing and reachability information between edge routers on the Internet', 'BGP is crucial for managing connections in large scale cloud environments.', 'active'),
('60000000-0000-0000-0000-000000000777', '50000000-0000-0000-0000-000000000046', 'expert', 'mcq', 'What is "Zero Trust" architecture?', '["Trusting nobody", "A security model that requires strict identity verification for every person and device trying to access resources on a private network", "A cloud with no password", "A network with no firewalls"]', 'A security model that requires strict identity verification for every person and device trying to access resources on a private network', 'Zero trust assumes that threats exist both inside and outside the network.', 'active'),
('60000000-0000-0000-0000-000000000778', '50000000-0000-0000-0000-000000000046', 'expert', 'mcq', 'Explain "Anycast" routing.', '["Sending to all nodes", "A network addressing and routing method in which incoming requests can be routed to a variety of different nodes in a group", "A type of Wi-Fi", "A database backup"]', 'A network addressing and routing method in which incoming requests can be routed to a variety of different nodes in a group', 'Anycast is used to improve latency and availability (e.g., in CDNs).', 'active');

-- Topic 47: Docker & CI/CD Pipelines (13 Questions)
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
-- Simple
('60000000-0000-0000-0000-000000000779', '50000000-0000-0000-0000-000000000047', 'simple', 'mcq', 'What is a "Dockerfile"?', '["A document about Docker history", "A text document that contains all the commands a user could call on the command line to assemble an image", "A type of database", "A network config"]', 'A text document that contains all the commands a user could call on the command line to assemble an image', 'Dockerfiles define the steps to build a Docker image.', 'active'),
('60000000-0000-0000-0000-000000000780', '50000000-0000-0000-0000-000000000047', 'simple', 'mcq', 'What does "CI" stand for in DevOps?', '["Container Inclusion", "Continuous Integration", "Cloud Integration", "Client Interaction"]', 'Continuous Integration', 'CI is the practice of automating the integration of code changes from multiple contributors into a single software project.', 'active'),
('60000000-0000-0000-0000-000000000781', '50000000-0000-0000-0000-000000000047', 'simple', 'mcq', 'What does "CD" stand for in DevOps?', '["Cloud Deployment", "Continuous Delivery / Deployment", "Container Development", "Centralized Data"]', 'Continuous Delivery / Deployment', 'CD automates the release of the validated code to a repository or production environment.', 'active'),
('60000000-0000-0000-0000-000000000782', '50000000-0000-0000-0000-000000000047', 'simple', 'mcq', 'Which tool is commonly used for CI/CD pipelines?', '["Excel", "Jenkins", "Photoshop", "Spotify"]', 'Jenkins', 'Jenkins is a popular open-source automation server for CI/CD.', 'active'),
-- Intermediate
('60000000-0000-0000-0000-000000000783', '50000000-0000-0000-0000-000000000047', 'intermediate', 'mcq', 'What is a "Docker Image"?', '["A picture of a whale", "A lightweight, standalone, executable package of software including everything needed to run it", "A running container", "A type of VM"]', 'A lightweight, standalone, executable package of software including everything needed to run it', 'Docker images are the building blocks of containers.', 'active'),
('60000000-0000-0000-0000-000000000784', '50000000-0000-0000-0000-000000000047', 'intermediate', 'mcq', 'What is "Blue-Green Deployment"?', '["A design choice linked to colors", "A deployment strategy that uses two identical production environments (Blue and Green) to reduce downtime and risk", "Testing on two different regions", "A type of UI theme"]', 'A deployment strategy that uses two identical production environments (Blue and Green) to reduce downtime and risk', 'One environment (e.g., Green) is live, while the other (Blue) is the staging area for the new release.', 'active'),
('60000000-0000-0000-0000-000000000785', '50000000-0000-0000-0000-000000000047', 'intermediate', 'mcq', 'What is a "Pipeline" in CI/CD?', '["A physical pipe", "A set of automated processes that allow developers to reliably and efficiently compile, build, and deploy their code", "A database table", "A network route"]', 'A set of automated processes that allow developers to reliably and efficiently compile, build, and deploy their code', 'Pipelines ensure consistent and repeatable workflows.', 'active'),
('60000000-0000-0000-0000-000000000786', '50000000-0000-0000-0000-000000000047', 'intermediate', 'mcq', 'What is "Container Registry"?', '["A list of all containers in the world", "A repository for storing and managing container images", "A type of firewall", "A cloud-based IDE"]', 'A repository for storing and managing container images', 'Examples include Docker Hub, Amazon ECR, and Google Container Registry.', 'active'),
-- Expert
('60000000-0000-0000-0000-000000000787', '50000000-0000-0000-0000-000000000047', 'expert', 'mcq', 'Explain "Canary Deployment".', '["Using birds in a datacenter", "A deployment strategy where a new version is rolled out to a small subset of users before a full release", "Stopping all servers", "A type of database indexing"]', 'A deployment strategy where a new version is rolled out to a small subset of users before a full release', 'Canary releases help detect issues early with minimal user impact.', 'active'),
('60000000-0000-0000-0000-000000000788', '50000000-0000-0000-0000-000000000047', 'expert', 'mcq', 'What is "GitOps"?', '["A type of Git branch", "An operational framework that takes DevOps best practices used for application development and applies them to infrastructure automation", "A Git command", "Using Git for social media"]', 'An operational framework that takes DevOps best practices used for application development and applies them to infrastructure automation', 'GitOps uses Git as the single source of truth for declarative infrastructure.', 'active'),
('60000000-0000-0000-0000-000000000789', '50000000-0000-0000-0000-000000000047', 'expert', 'mcq', 'What is "Mutation Testing"?', '["Testing for biological viruses", "A type of software testing where small changes (mutations) are introduced to the code to see if the tests catch them", "A design pattern", "Scaling the app automatically"]', 'A type of software testing where small changes (mutations) are introduced to the code to see if the tests catch them', 'Mutation testing evaluates the quality and effectiveness of existing test suites.', 'active'),
('60000000-0000-0000-0000-000000000790', '50000000-0000-0000-0000-000000000047', 'expert', 'mcq', 'Explain the concept of "Infrastructure as Code" (IaC) in a CI/CD pipeline.', '["Writing code for buildings", "Managing and provisioning infrastructure through machine-readable definition files rather than physical hardware configuration", "A type of UI layout", "A network routing protocol"]', 'Managing and provisioning infrastructure through machine-readable definition files rather than physical hardware configuration', 'IaC allows for automated and repeatable infrastructure deployments.', 'active'),
('60000000-0000-0000-0000-000000000791', '50000000-0000-0000-0000-000000000047', 'expert', 'mcq', 'What is a "Multi-stage Build" in Docker?', '["Building on different floors", "A Docker feature that allows using multiple FROM statements in a single Dockerfile to optimize image size", "A type of database backup", "A cloud region spread"]', 'A Docker feature that allows using multiple FROM statements in a single Dockerfile to optimize image size', 'Multi-stage builds help separate the build environment from the final runtime environment.', 'active');

-- Topic 48: Infrastructure as Code (Terraform) (9 Questions)
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
-- Simple
('60000000-0000-0000-0000-000000000792', '50000000-0000-0000-0000-000000000048', 'simple', 'mcq', 'What is Terraform?', '["A landscaping tool", "An open-source infrastructure as code software tool", "A cloud provider", "A type of database"]', 'An open-source infrastructure as code software tool', 'Terraform allows you to define and provide data center infrastructure using a declarative configuration language.', 'active'),
('60000000-0000-0000-0000-000000000793', '50000000-0000-0000-0000-000000000048', 'simple', 'mcq', 'What is "HCL" in Terraform?', '["Hyper Cloud Language", "HashiCorp Configuration Language", "Hardware Control Logic", "Hybrid Connection Link"]', 'HashiCorp Configuration Language', 'HCL is the language used to write Terraform configurations.', 'active'),
('60000000-0000-0000-0000-000000000794', '50000000-0000-0000-0000-000000000048', 'simple', 'mcq', 'What does "terraform init" do?', '["Deletes the cloud account", "Initializes a working directory containing Terraform configuration files", "Starts a new VM", "Creates a billing report"]', 'Initializes a working directory containing Terraform configuration files', 'init is the first command that should be run after writing a new Terraform configuration.', 'active'),
-- Intermediate
('60000000-0000-0000-0000-000000000795', '50000000-0000-0000-0000-000000000048', 'intermediate', 'mcq', 'What is a Terraform "Provider"?', '["A cloud vendor like AWS or Azure", "A plugin that Terraform uses to interact with cloud providers, SaaS providers, and other APIs", "A type of IAM role", "A network switch"]', 'A plugin that Terraform uses to interact with cloud providers, SaaS providers, and other APIs', 'Providers enable Terraform to manage a wide range of services.', 'active'),
('60000000-0000-0000-0000-000000000796', '50000000-0000-0000-0000-000000000048', 'intermediate', 'mcq', 'What is the purpose of "Terraform State"?', '["To show the current CPU usage", "To keep track of the resources Terraform manages and map them to your configuration", "To store passwords", "A type of UI state"]', 'To keep track of the resources Terraform manages and map them to your configuration', 'State is used by Terraform to map real world resources to your configuration.', 'active'),
('60000000-0000-0000-0000-000000000797', '50000000-0000-0000-0000-000000000048', 'intermediate', 'mcq', 'What does "terraform plan" show?', '["The price of the cloud resources", "The set of changes that Terraform will perform to match your configuration", "A graph of dependencies", "All errors in the code"]', 'The set of changes that Terraform will perform to match your configuration', 'plan lets you preview changes before applying them.', 'active'),
-- Expert
('60000000-0000-0000-0000-000000000798', '50000000-0000-0000-0000-000000000048', 'expert', 'mcq', 'What are Terraform "Modules"?', '["Physical hardware modules", "Self-contained packages of Terraform configurations that managed related resources", "A type of cloud region", "A network policy"]', 'Self-contained packages of Terraform configurations that managed related resources', 'Modules are used to create reusable, shared abstractions of infrastructure.', 'active'),
('60000000-0000-0000-0000-000000000799', '50000000-0000-0000-0000-000000000048', 'expert', 'mcq', 'Explain "Terraform Workspace".', '["An office space", "A feature to manage multiple separate states within a single configuration directory", "A cloud-based IDE", "A project management tool"]', 'A feature to manage multiple separate states within a single configuration directory', 'Workspaces allow you to manage different environments (e.g., prod vs dev) easily.', 'active'),
('60000000-0000-0000-0000-000000000800', '50000000-0000-0000-0000-000000000048', 'expert', 'mcq', 'What is a "Backend" in Terraform?', '["The server where the app runs", "A configuration that determines how state is stored and where operations are performed", "A type of database", "The last step of a code block"]', 'A configuration that determines how state is stored and where operations are performed', 'Backends allow for remote state storage (e.g., in S3 or Azure Blob) and state locking.', 'active');
